<?php
function inflow_cancel_form($id){return '<form method="post" action="actions.php" data-confirm="Cancel this pending inflow? No inventory will be added. The uploaded file remains in history as Cancelled."><input type="hidden" name="action" value="cancel_inflow_upload"><input type="hidden" name="batch_id" value="'.(int)$id.'"><input type="hidden" name="return" value="inflow"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><button type="submit" class="btn ghost">Cancel Upload</button></form>';}
function inflow_cancelled_message($b){$r=json_decode($b['result_json']??'[]',true)?:[];return '<div class="alert info"><b>Inflow Cancelled</b><p>No inventory was added. Cancelled by '.e($r['cancelled_name']??'').' on '.e($r['cancelled_at']??'').'. The original upload remains in history. Upload it again to process it later.</p></div>';}
function cancel_inflow_upload($bid,$uid){
 $pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();if(!$b)throw new Exception('Inflow upload not found.');
 if($b['status']==='Cancelled'){$pdo->commit();return;}
 if(!in_array($b['batch_type'],['Receipt PDF','Excel Upload','Manual'],true)||!in_array($b['status'],['To Review','Unsuccessful'],true))throw new Exception('Only unposted inflow uploads can be cancelled. Confirmed transactions cannot be cancelled here.');
 $q=$pdo->prepare('SELECT COUNT(*) FROM inflows WHERE batch_id=?');$q->execute([$bid]);if($q->fetchColumn())throw new Exception('This inflow already has posted stock and cannot be cancelled.');
 $r=json_decode($b['result_json']??'[]',true)?:[];$r['cancelled_by']=(int)$uid;$r['cancelled_name']=current_user()['name'];$r['cancelled_at']=date('Y-m-d H:i:s');
 $pdo->prepare("UPDATE inflow_batches SET status='Cancelled',result_json=? WHERE id=?")->execute([json_encode($r),$bid]);audit('Cancel inflow upload','Inflow Batch',$b['batch_ref'],'Pending upload cancelled; no inventory added.');$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function stage_bulk_inflow($file,$uid){validate_upload_file($file,['xlsx']);
 $pdo=db();inflow_supplier($_POST['supplier']??'');inflow_upload_check($file);$stored=store_upload($file,'inflow_bulk','INFXLSX');try{$rows=XlsxReader::rows(__DIR__.'/'.$stored);$hr=find_header_row($rows,[['item','quantity'],['product','quantity']]);if($hr===null)throw new Exception('Inflow file needs Item/Product, Quantity and Reference. Optional: UOM, Date.');}catch(Throwable $e){return save_bulk_inflow_draft($stored,$file,$uid,[],[$e->getMessage()]);}$h=array_map('norm',$rows[$hr]);$ix=function($names)use($h){foreach($names as $n){$i=array_search($n,$h,true);if($i!==false)return $i;}return null;};$ii=$ix(['item','product']);$qi=$ix(['quantity']);$ri=$ix(['reference','reference no','dr','dr no','order id']);$ui=$ix(['uom','unit','units']);$di=$ix(['date']);$lines=[];$errors=[];$total=0;$seen=[];
 foreach(array_slice($rows,$hr+1) as $i=>$row){if(!array_filter($row,fn($v)=>trim($v)!==''))continue;$rn=$hr+$i+2;$item=trim($row[$ii]??'');try{if($item==='')throw new Exception('Product is required.');$q=$pdo->prepare('SELECT id FROM products WHERE active=1 AND (normalized_name=? OR master_sku=?) LIMIT 1');$q->execute([norm($item),$item]);$pid=product_code_lookup($item)?:$q->fetchColumn();if(!$pid)throw new Exception($item.' not found in active Product Master');$raw=trim($row[$qi]??'');if(!is_numeric($raw)||(float)$raw<=0)throw new Exception('Quantity must be positive.');$uom=$ui!==null?trim($row[$ui]??'pc'):'pc';[$factor,$qty]=receipt_quantity((float)$raw,$uom);if($qty<=0||$qty>100000000)throw new Exception('Quantity is outside the supported range.');$date=$di!==null?trim($row[$di]??''):date('Y-m-d');if($date===''||(!is_numeric($date)&&strtotime($date)===false))throw new Exception('A valid date is required.');$date=excel_date($date);$ref=$ri!==null?trim($row[$ri]??''):'';if($ref==='')throw new Exception('DR / Receipt Reference is required.');if(strlen($ref)>100)throw new Exception('Reference is too long.');$rowKey=hash('sha256',json_encode([$pid,$date,norm($ref),(float)$raw,norm($uom)]));if(isset($seen[$rowKey]))throw new Exception('Duplicate row inside this file. Consolidate or remove the repeated row before uploading.');$seen[$rowKey]=true;$lines[]=['row'=>$rn,'item'=>$item,'product_id'=>(int)$pid,'source_qty'=>(float)$raw,'source_uom'=>$uom,'conversion_factor'=>$factor,'qty'=>$qty,'date'=>$date,'reference'=>$ref];$total+=$qty;}catch(Throwable $e){$errors[]='Row '.$rn.': '.$e->getMessage();}}
 if(!$lines&&!$errors)$errors[]='No inflow rows found.';return save_bulk_inflow_draft($stored,$file,$uid,$lines,$errors);
}
function save_bulk_inflow_draft($stored,$file,$uid,$lines,$errors){$pdo=db();$ref=next_ref('INF');$status=$errors?'Unsuccessful':'To Review';$r=['bulk_review_version'=>1,'bulk_rows'=>$lines];$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO inflow_batches(batch_ref,batch_type,source_name,reference_no,txn_date,attachment_path,original_filename,status,total_qty,error_count,error_json,result_json,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$ref,'Excel Upload',inflow_supplier($_POST['supplier']??''),basename($file['name']),date('Y-m-d'),$stored,basename($file['name']),$status,0,count($errors),json_encode($errors),json_encode($r),$uid]);$bid=(int)$pdo->lastInsertId();inflow_record_hash($bid,$stored);audit('Review bulk inflow','Inflow Batch',$ref,count($lines).' valid rows; no inventory added.');$pdo->commit();return $bid;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function confirm_bulk_inflow($bid,$uid){
 $pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();$r=json_decode($b['result_json']??'[]',true)?:[];if(!$b||$b['batch_type']!=='Excel Upload'||$b['status']!=='To Review'||empty($r['bulk_rows'])||$b['error_count'])throw new Exception('This bulk inflow is not ready for confirmation.');$q=$pdo->prepare('SELECT COUNT(*) FROM inflows WHERE batch_id=?');$q->execute([$bid]);if($q->fetchColumn())throw new Exception('This inflow already has posted stock.');$allocation=checked_incoming_allocation($b);inflow_duplicate_review($b,true);$total=0;$ins=$pdo->prepare('INSERT INTO inflows(batch_id,txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');
 foreach($r['bulk_rows'] as $line){active_product($line['product_id']);[$factor,$qty]=receipt_quantity($line['source_qty'],$line['source_uom']);if($factor!==(int)$line['conversion_factor']||$qty!==(int)$line['qty'])throw new Exception('Bulk quantity validation changed. Upload a corrected file.');$ins->execute([$bid,$line['date'],$line['reference'],'','',$line['product_id'],$line['source_qty'],$line['source_uom'],$factor,$qty,'Bulk Inflow','',$uid]);$total+=$qty;}
 $r=post_incoming_allocation($b,$allocation,$uid);$r['confirmed_by']=(int)$uid;$r['confirmed_at']=date('Y-m-d H:i:s');$pdo->prepare("UPDATE inflow_batches SET status='Confirmed',total_qty=?,result_json=? WHERE id=?")->execute([$total,json_encode($r),$bid]);audit('Confirm bulk inflow','Inflow Batch',$b['batch_ref'],count($r['bulk_rows']).' lines / '.$total.' pcs');$pdo->commit();return $total;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function inflow_pending_details($b){
 $r=json_decode($b['result_json']??'[]',true)?:[];if($b['status']==='Cancelled'){echo inflow_cancelled_message($b);return;}
 if($b['batch_type']==='Manual'&&$b['status']==='To Review'){echo '<div class="alert info">No inventory has been added. Review the incoming item and its platform allocation before Confirm Inflow.</div>';if(can_action('cancel_inflow_upload'))echo inflow_cancel_form($b['id']);return;}
 if($b['batch_type']!=='Excel Upload'||!in_array($b['status'],['To Review','Unsuccessful'],true))return;
 if(can_action('cancel_inflow_upload'))echo '<div class="card modal-actions">'.inflow_cancel_form($b['id']).'</div>';
 if(empty($r['bulk_review_version']))return;echo '<div class="alert info">Review this bulk upload. No inventory has been added. Continue to Platform Allocation, then Confirm Inflow to post stock.</div><div class="card table-wrap"><h3>Bulk Inflow Review</h3><table class="table"><tr><th>Row</th><th>Product</th><th>Date</th><th>Source Qty</th><th>Unit</th><th>Inventory Qty</th></tr>';foreach($r['bulk_rows']??[] as $line)echo '<tr><td>'.(int)$line['row'].'</td><td>'.e($line['item']).'</td><td>'.e($line['date']).'</td><td>'.e($line['source_qty']).'</td><td>'.e($line['source_uom']).'</td><td>'.(int)$line['qty'].' pcs</td></tr>';echo '</table>';
 if($b['error_count'])echo '<div class="alert warn">'.e(implode(' · ',json_decode($b['error_json']??'[]',true)?:[])).'<p>Correct the file and upload it again, or Cancel Upload. No stock was posted.</p></div>';
 elseif(can_action('confirm_bulk_inflow'))echo '<a class="btn primary" href="?page=inflow_allocation&id='.(int)$b['id'].'">Continue to Platform Allocation</a>';echo '</div>';
}
